# Just compute the expected output by carefully following demo patterns
# The rule seems to be:
# 1. Find row with most 2s → spine row
# 2. Fill horizontal spine from leftmost to rightmost 2
# 3. For each off-spine 2: find a "projection point" on the spine and fill vertically
# 4. For rows connecting spine to off-spine 2s, fill horizontally between vertical fill columns

def compute_test(grid):
    """Compute test output using spine rule with careful horizontal filling"""
    rows_data = {}
    for r in range(len(grid)):
        cols_2 = [c for c in range(len(grid[0])) if grid[r][c] == 2]
        rows_data[r] = cols_2

    # Find spine row (most 2s)
    spine_row = max(rows_data.keys(), key=lambda x: len(rows_data[x]))

    spine_2s = sorted(rows_data[spine_row])
    if not spine_2s:
        return None  # No 2s at all
    left_2 = spine_2s[0]
    right_2 = spine_2s[-1]

    # Initialize output
    output = [row[:] for row in grid]

    # Center = vertical spans
    center_cols = []
    for r in range(len(grid)):
        if r == spine_row:
            center_cols.append((r, c) for c in range(left_2 + 1, right_2))
        else:
            # Find vertical spans: where do the 2s connect?
            for c in rows_data[r]:
                # Does column c contain a 2?
                pass

    # Actually, let me just use the rule from demo 2:
    # Vertical fills connect off-spine 2s to the spine row (exclusive of spine)
    # Horizontal fills at rows between spine and off-spine 2s connect adjacent vertical fills

    output = [row[:] for row in grid]

    # Step 1: Horizontal spine (fill between leftmost and rightmost spine 2)
    for c in range(left_2 + 1, right_2):
        output[spine_row][c] = 3

    # Step 2: Find off-spine 2s and their vertical connections
    vertical_cols = []  # columns that have vertical fills
    vertical_spans = {}  # col -> (r_min, r_max)

    for r, cols_2 in rows_data.items():
        if r == spine_row:
            continue
        for c in cols_2:
            if c not in vertical_cols:
                vertical_cols.append(c)
            vertical_span = vertical_spans.get(c, [-1, -1])
            if 0 <= r:
                vertical_span[0] = max(vertical_span[0], r)
            if r + 1 < len(grid):
                vertical_span[1] = min(vertical_span[1], r + 1)
            if 0 <= vertical_span[0] <= vertical_span[1] < len(grid):
                vertical_spans[c] = vertical_span

    # Fill verticals
    for c, (start_row, end_row) in vertical_spans.items():
        for rr in range(start_row, end_row):
            output[rr][c] = 3

    # Step 3: Horizontal fills in rows between spine and off-spine 2s
    # Fill between leftmost and rightmost vertical fill columns
    row_data = rows_data
    for r in row_data:
        if r == spine_row or len(rows_data[r]) == 0:
            continue
        # Find vertical fill columns in this row
        vert_c = [c for c in range(len(grid[0])) if output[r][c] == 3]
        if len(vert_c) >= 2:
            left_v = min(vert_c)
            right_v = max(vert_c)
            # Fill from (left_v + 1) to (right_v - 2) exclusive? No, just fill between
            for c in range(left_v, right_v):
                if output[r][c] == 3:
                    pass
            # Actually fill horizontally (if there's a gap)
            for c in range(left_v, right_v + 1):
                if output[r][c] == 3:
                    pass  # Already filled
            # Handle 2s on this row
            for c in range(len(grid[0])):
                if output[r][c] == 2:
                    pass  # Keep 2
                elif output[r][c] == 0 and left_v <= c < right_v:
                    output[r][c] = 3

    return output

