# Let me implement and test the full rule, including potential horizontal connections

def compute_full_rule(in_grid):
    from collections import defaultdict

    rows, cols = len(in_grid), len(in_grid[0])
    output = [row[:] for row in in_grid]

    rows_data = defaultdict(list)
    for r in range(rows):
        for c in range(cols):
            if in_grid[r][c] == 2:
                rows_data[r].append(c)

    if not rows_data:
        return output

    spine_row = max(rows_data.keys(), key=lambda x: len(rows_data[x]))
    spine_2s = sorted(rows_data[spine_row])

    # 1. Horizontal spine fill
    for c in range(spine_2s[0] + 1, spine_2s[-1]):
        output[spine_row][c] = 3

    # 2. Vertical fills from off-spine 2s toward spine
    off_spine_2s = []
    for r in range(rows):
        for c in rows_data[r]:
            if r != spine_row:
                off_spine_2s.append((r, c))

    for (r, c) in off_spine_2s:
        if r < spine_row:
            for rr in range(r + 1, spine_row):
                output[rr][c] = 3
        else:
            for rr in range(spine_row + 1, r):
                output[rr][c] = 3

    # 3. Now: for each row that has 3s, check if there are multiple vertical columns
    # and if so, fill horizontally between them
    # BUT only for rows that are between spine and an off-spine 2 (not at the same level)

    for r in range(rows):
        if r == spine_row:
            continue
        vert_cols = [c for c in range(cols) if output[r][c] == 3]
        if len(vert_cols) >= 2:
            left_fill = min(vert_cols)
            right_fill = max(vert_cols)
            for c in range(left_fill, right_fill):
                if output[r][c] == 0:
                    output[r][c] = 3

    return output

